async function digest(s){const bytes=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(s));return [...new Uint8Array(bytes)].map(b=>b.toString(16).padStart(2,'0')).join('')}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;e.preventDefault();try{await action(b.dataset.action)}catch(error){console.error(error);toast('처리하지 못했어요. 입력 내용을 확인하고 다시 시도해 주세요.')}});
