function exportXlsx(a){if(!a)return;const cols=['번호','작업','위험요인','사고유형','현재 신호','현재 안전조치','개선대책','개선 후 예상','담당자','예정일','실제 결과','완료일','조치 후 사진 수','조치 후 신호','산정 이유','회차'];const rows=[['Safe-T 위험성평가표',a.status==='draft'?'미확정':'확정'],['평가표명',a.title],['사업장',a.businessName,'업종',a.industry],['평가일',a.date,'담당자',a.author],['참여자',a.participants.map(p=>p.name).join(', ')],['확정일',a.confirmedAt||''],['안내','프로토타입 예시 · 실제 모델 판정 미연결'],[],cols,...a.rows.map((r,i)=>{const x=r.actions.at(-1);return[i+1,r.work,r.hazard,r.accident,labels[r.signal],r.none?'현재 조치 없음':selected(r,'current').join('\n'),needsPlan(r)?selected(r,'plans').join('\n'):'현재 상태 유지',r.expected?labels[r.expected]:'',r.owner,r.due,x?.result||'',x?.date||'',x?.photos.length||'',x?labels[x.signal]:'',x?.reason||'',x?.round||'']}),[],['서명자','서명 여부','서명 시각'],...a.participants.map(p=>{const s=a.signatures.find(s=>s.participantId===p.id);return[p.name,s?'서명 완료':'서명 필요',s?.signedAt||'']})];const colname=n=>{let s='';for(n++;n;n=Math.floor((n-1)/26))s=String.fromCharCode(65+(n-1)%26)+s;return s};const sheet='<?xml version="1.0" encoding="UTF-8"?><worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><cols>'+cols.map((c,i)=>'<col min="'+(i+1)+'" max="'+(i+1)+'" width="'+([2,5,6,10,14].includes(i)?40:20)+'" customWidth="1"/>').join('')+'</cols><sheetData>'+rows.map((r,i)=>'<row r="'+(i+1)+'">'+r.map((c,j)=>'<c r="'+colname(j)+(i+1)+'" t="inlineStr"><is><t xml:space="preserve">'+xml(c)+'</t></is></c>').join('')+'</row>').join('')+'</sheetData></worksheet>';
download(zip({'[Content_Types].xml':'<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/></Types>','_rels/.rels':'<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>','xl/workbook.xml':'<workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets><sheet name="위험성평가" sheetId="1" r:id="rId1"/></sheets></workbook>','xl/_rels/workbook.xml.rels':'<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/></Relationships>','xl/worksheets/sheet1.xml':sheet}),a.title.replace(/[\\/:*?"<>|]/g,'_')+'_'+a.date+'_'+(a.status==='draft'?'미확정':'확정')+'.xlsx');toast('전체 '+a.rows.length+'개 항목을 엑셀로 내려받았어요.')}
async function exportPDF(a){await document.fonts.ready;const pages=[],W=1240,H=1754,margin=80;let c,ctx,y;function start(){c=document.createElement('canvas');c.width=W;c.height=H;ctx=c.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,W,H);ctx.fillStyle='#185a45';ctx.font='bold 24px "Noto Sans KR","Malgun Gothic",sans-serif';ctx.fillText('Safe-T  |  확정 위험성평가표',margin,70);ctx.font='18px "Noto Sans KR","Malgun Gothic",sans-serif';ctx.fillStyle='#66796b';ctx.fillText('화면 검토용 예시 · 실제 안전 판정 아님',margin,H-40);y=125}function finish(){pages.push(c.toDataURL('image/jpeg',.9))}function text(t,size=22,bold=false,color='#263e32'){ctx.font=(bold?'bold ':'')+size+'px "Noto Sans KR","Malgun Gothic",sans-serif';let line='';for(const char of String(t)){if(char==='\n'||ctx.measureText(line+char).width>W-margin*2){if(y>H-100){finish();start();ctx.font=(bold?'bold ':'')+size+'px "Noto Sans KR","Malgun Gothic",sans-serif'}ctx.fillStyle=color;ctx.fillText(line,margin,y);y+=size*1.7;line=char==='\n'?'':char}else line+=char}if(line){if(y>H-100){finish();start();ctx.font=(bold?'bold ':'')+size+'px "Noto Sans KR","Malgun Gothic",sans-serif'}ctx.fillStyle=color;ctx.fillText(line,margin,y);y+=size*1.7}}
start();text(a.title,34,true);text(a.businessName+' · '+a.industry,23);text('평가일 '+a.date+'  |  담당자 '+a.author);text('확정일 '+kdate(a.confirmedAt));text('참여자 '+a.participants.map(p=>p.name).join(', '));y+=20;
a.rows.forEach((r,i)=>{if(y>H-420){finish();start()}text(String(i+1).padStart(2,'0')+'. '+r.work+' — '+labels[r.signal],26,true);text(r.hazard);text('현재 안전조치: '+(r.none?'현재 조치 없음':selected(r,'current').join(' · ')));text('개선대책: '+(needsPlan(r)?selected(r,'plans').join(' · '):'현재 상태 유지'));if(needsPlan(r)){text('담당자: '+r.owner+'  |  예정일: '+r.due);text('개선 후 예상: '+labels[r.expected||'off']+' (시연 예시)')}y+=22});text('참여자 서명 현황',26,true);a.participants.forEach(p=>{const s=a.signatures.find(s=>s.participantId===p.id);text(p.name+' · '+(s?'서명 완료 · '+s.signedAt:'서명 필요'))});text('서명 원본과 연락처는 포함하지 않습니다.',18);finish();download(makePDF(pages,W,H),a.title.replace(/[\\/:*?"<>|]/g,'_')+'_'+a.date+'_확정.pdf');toast('전체 평가표 PDF를 내려받았어요.')}
function makePDF(images,w,h){const enc=new TextEncoder(),chunks=[],offsets=[0];let length=0;const push=v=>{const b=typeof v==='string'?enc.encode(v):v;chunks.push(b);length+=b.length};const object=(n,body)=>{offsets[n]=length;push(n+' 0 obj\n');push(body);push('\nendobj\n')};push('%PDF-1.4\n');object(1,'<< /Type /Catalog /Pages 2 0 R >>');object(2,'<< /Type /Pages /Count '+images.length+' /Kids ['+images.map((_,i)=>(3+i*3)+' 0 R').join(' ')+'] >>');images.forEach((img,i)=>{const n=3+i*3,jpeg=Uint8Array.from(atob(img.split(',')[1]),c=>c.charCodeAt(0));object(n,'<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595.28 841.89] /Resources << /XObject << /Im'+i+' '+(n+1)+' 0 R >> >> /Contents '+(n+2)+' 0 R >>');offsets[n+1]=length;push((n+1)+' 0 obj\n<< /Type /XObject /Subtype /Image /Width '+w+' /Height '+h+' /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length '+jpeg.length+' >>\nstream\n');push(jpeg);push('\nendstream\nendobj\n');const stream='q\n595.28 0 0 841.89 0 0 cm\n/Im'+i+' Do\nQ';object(n+2,'<< /Length '+enc.encode(stream).length+' >>\nstream\n'+stream+'\nendstream')});const xref=length;push('xref\n0 '+offsets.length+'\n0000000000 65535 f \n');for(let i=1;i<offsets.length;i++)push(String(offsets[i]).padStart(10,'0')+' 00000 n \n');push('trailer\n<< /Size '+offsets.length+' /Root 1 0 R >>\nstartxref\n'+xref+'\n%%EOF');return new Blob(chunks,{type:'application/pdf'})}
